#include <stdio.h>
#include <string.h>

/* 页表：8 个页 -> 页框号；-1 表示未分配 */
int page_table[8] = {2, 5, 1, 7, 0, 3, -1, 6};
#define PAGE_SIZE 4096

int tlb_page[4] = {-1, -1, -1, -1};   /* TLB：4 项，LRU */
int tlb_frame[4];
int lru_tick[4];
int hits = 0, misses = 0, tick = 0;

int tlb_lookup(int page) {
    for (int i = 0; i < 4; i++) if (tlb_page[i] == page) {
        lru_tick[i] = ++tick; hits++; return tlb_frame[i];
    }
    misses++;
    return -1;
}
void tlb_insert(int page, int frame) {
    int victim = 0;
    for (int i = 0; i < 4; i++) if (tlb_page[i] == -1) { victim = i; goto ins; }
    for (int i = 1; i < 4; i++) if (lru_tick[i] < lru_tick[victim]) victim = i;
ins:
    tlb_page[victim] = page; tlb_frame[victim] = frame; lru_tick[victim] = ++tick;
}

int main(void) {
    /* 逻辑地址序列（十进制） */
    long addrs[] = {0, 4096, 8192, 0, 4096, 16384, 8192, 0, 20480, 4096};
    int n = 10;
    printf("page size = %d B, page table has 8 entries\n", PAGE_SIZE);
    printf("addr       P     W    frame   physical   resolved_by\n");
    for (int i = 0; i < n; i++) {
        long a = addrs[i];
        int p = (int)(a / PAGE_SIZE), w = (int)(a % PAGE_SIZE);
        int frame = tlb_lookup(p);
        const char *src = "TLB";
        if (frame < 0) { frame = page_table[p]; src = "PT "; tlb_insert(p, frame); }
        long pa = (long)frame * PAGE_SIZE + w;
        printf("%-8ld  %-4d  %-4d  %-5d   %-8ld  %s\n", a, p, w, frame, pa,
               frame < 0 ? "INVALID PAGE" : src);
    }
    double h = (double)hits / (hits + misses);
    printf("TLB hits=%d misses=%d hit rate=%.0f%%\n", hits, misses, h * 100);
    printf("EAT (1-level PT, t=100ns) = t*(2-h) = %.1f ns\n", 100.0 * (2.0 - h));
    return 0;
}
